SET NOCOUNT ON; SELECT panel_code, col_name, place, data_type, required, hidden FROM yj_field WHERE col_name IN (N'仓库',N'仓库名称') AND panel_code IN ('PURCHASE_IN','SALE_OUT','SO_ORDER'); SELECT t.name, CASE WHEN COL_LENGTH('dbo.'+t.name,N'仓库') IS NULL THEN '缺仓库' ELSE '有仓库' END, CASE WHEN COL_LENGTH('dbo.'+t.name,N'仓库名称') IS NULL THEN '缺仓库名称' ELSE '有仓库名称' END FROM (VALUES (N'bl_purchase_in'),(N'bl_sale_out'),(N'bl_so_order'),(N'bd_purchase_in')) t(name);